(function () {
  const S = 4.2, D = 5.2, F = W.F, { seg, eio, lerp } = F;
  kit.scene('hall', {
    init(kit) {
      const M = W.MOODS.hospitalMint;
      kit.stage.append(kit.h(F.frame(W.bg.ward(M, { beds: false }) + W.prop.door(230, 655, 1.0, M) + '<g class="ha-board"><path d="M200 0 V40 M640 0 V40" ' + F.ln('#2A2522', 5) + '/><rect x="70" y="40" width="700" height="210" rx="14" ' + F.st('#FFFBEA', 6) + '/></g>' + F.lamp(980, 110, 1.0, 200) + F.lamp(1560, 110, 1.0, 200) + F.clock(1240, 360, 62, 'ha-clk') + F.picture(1600, 330, 180, 135) + F.plant(1820, 960, 1.1) + W.prop.bench(820, 960, 1.15, M) +
        W.person('ha-p1', { outfit: 'rags', hair: 'short', hairColor: 'black', facial: 'stubble', face: 0.3 }) +
        W.person('ha-p2', { outfit: 'rags', hat: 'straw', face: 0.3 }) +
        W.person('ha-p3', { outfit: 'peasant', hair: 'bun', hairColor: 'brown', face: 0.3 }) +
        W.person('ha-n', { outfit: 'scrubs', hair: 'bun', hairColor: 'brown', item: 'scroll', face: -0.3 }),
        F.label('Sadiki Hospital', 110, 55, 84, 'ha-t1') + F.label('Tunis', 110, 160, 70, 'ha-t2') + F.label('1909', 470, 160, 70, 'ha-t3', 'color:#B5503F'), '')));
      const q = F.q(kit.stage); this.root = kit.stage;
      this.p = ['ha-p1', 'ha-p2', 'ha-p3', 'ha-n'].map((c) => W.bindPerson(kit.stage, c));
      Object.assign(this, { cam: q('.cam'), t1: q('.ha-t1'), t2: q('.ha-t2'), t3: q('.ha-t3') });
    },
    render(t) {
      const a = t + S;
      F.cam(this.cam, a, S, S + D, 1.0, 1.06, 960, 700);
      const sit = { legL: -70, legR: -70 };
      W.posePerson(this.p[0], Object.assign({ x: 700, y: 1010, s: 1.5, expr: 'sad', blink: F.blink(a, 3.3), b1: 10, a1: -6, head: 2 * Math.sin(a) }, {}));
      W.posePerson(this.p[1], { x: 880, y: 1010, s: 1.5, expr: 'worried', blink: F.blink(a, 2.9, 1), head: -3 });
      W.posePerson(this.p[2], { x: 1050, y: 1010, s: 1.5, expr: 'neutral', blink: F.blink(a, 3.6, 2), a1: -12 });
      W.posePerson(this.p[3], { x: 1480, y: 1000, s: 1.7, expr: F.talk(a, [[6.9, 7.2]]) || 'neutral', blink: F.blink(a, 3.1, 0.7), a1: -40 + 4 * Math.sin(a * 2), a2: -50, head: 2 * Math.sin(a * 1.3) });
      W.pop(this.t1, a, 5.36, 'left'); W.pop(this.t2, a, 6.42, 'left'); W.pop(this.t3, a, 8.04, 'left');
    },
  });
})();
